#!/usr/bin/env bash
# Collect repo guidance: root candidates plus scoped instruction files from
# each changed file's ancestor dirs (per directory, in Muse's
# documented check order: AGENTS.md, CLAUDE.md, .agents/AGENTS.md,
# .claude/CLAUDE.md). Per directory level only the FIRST existing file
# in that order applies — Muse's own loading rule — so lower-priority
# siblings are omitted rather than presented as concurrent guidance,
# while a differing base winner is still retained: it governed the
# change even when the head winner is a different sibling. Default-branch
# base versions are
# trusted; custom-base versions are still emitted from the captured base
# SHA labeled UNTRUSTED (unreachable today — the job `if` admits only
# default-base PRs; kept as defense in depth), as are all head fallbacks.
#
# Env in: RUNNER_TEMP, SCRIPT_DIR. Reads muse-vars.env, muse-files.json.
# Files out: muse-guidance.md. Must run from the checked-out PR head: head
# fallbacks are read from the working tree, base versions from FETCH_HEAD.
set -euo pipefail

# shellcheck disable=SC1091  # generated by collect.sh at run time
. "${RUNNER_TEMP}/muse-vars.env"
if [[ "${MUSE_STOP:-1}" == "1" ]]; then exit 0; fi
# shellcheck disable=SC1091  # SCRIPT_DIR is set by the workflow step
. "${SCRIPT_DIR}/lib.sh"

trust_base_flag="$(trust_base "${MUSE_BASE_REF}" "${MUSE_DEFAULT_BRANCH:-}" "${MUSE_BASE_AVAILABLE}")"
guidance_file="${RUNNER_TEMP}/muse-guidance.md"
: > "${guidance_file}"
guidance_bytes=0
guidance_budget=96000
guidance_cap=32000
guidance_capped=false
guidance_truncated=false
emit_guidance() {
  candidate="$1"
  phase="$2"
  if [[ "${guidance_capped}" == "true" ]]; then return 0; fi
  content=""
  source=""
  # Phase is pre-classified by the caller (one git show per candidate), so
  # emit only reads from its assigned source instead of probing again.
  if [[ "${phase}" == "base" ]] \
    && content="$(git show "${MUSE_BASE_SHA_FULL}:${candidate}" 2>/dev/null)"; then
    # SHA, not the branch name: branch names are submitter-controlled and
    # this label prints outside any untrusted block.
    source="trusted (base ${MUSE_BASE_SHA_FULL:0:10})"
  elif [[ "${phase}" == "xbase" ]] \
    && content="$(git show "${MUSE_BASE_SHA_FULL}:${candidate}" 2>/dev/null)"; then
    # Custom-base content from the captured SHA (never the branch name, and
    # the classifier already verified the base is available). Skip when the
    # head carries identical content — the head emission covers it — but
    # keep it when head deleted or changed the file: those base-side rules
    # still governed the change under review.
    if head_readable "${candidate}" \
      && [[ "$(cat -- "${candidate}")" == "${content}" ]]; then
      return 0
    fi
    source="UNTRUSTED (custom base ${MUSE_BASE_SHA_FULL:0:10})"
  elif [[ "${phase}" == "head" ]] && head_readable "${candidate}"; then
    # Refuse symlinks: a PR-added symlink (e.g. to /proc/self/environ, or a
    # symlinked parent dir) would otherwise embed runner secrets into the
    # prompt. The -- keeps option-like paths (e.g. --help/AGENTS.md) from
    # parsing as flags and aborting the step under set -e.
    content="$(cat -- "${candidate}")"
    source="UNTRUSTED (PR head)"
  else
    return 0
  fi
  trunc_note=""
  if (( $(printf '%s' "${content}" | wc -c) > guidance_cap )); then
    # Byte-bounded (not char-based): a multibyte file cut by chars could
    # still exceed the aggregate budget and starve later guidance.
    content="$(bound_untrusted "${content}" "${guidance_cap}")"
    trunc_note=" [TRUNCATED at ${guidance_cap} bytes]"
    guidance_truncated=true
  fi
  # Candidate paths from changed files are submitter-controlled: flatten
  # newlines for display and omit the path from the block attribute (a quote
  # in the path would break out of it). The 300-char cut is a display label,
  # not a byte budget, so char-based slicing is correct here.
  safe_candidate="$(printf '%s' "${candidate}" | tr '\n' '_' | neutralize_tags)"
  safe_candidate="${safe_candidate:0:300}"
  # Budget the whole rendered block (heading, label, wrapper), not just
  # the content: hundreds of short files under long paths could otherwise
  # overshoot the aggregate budget severalfold with no warning.
  if [[ "${source}" == UNTRUSTED* ]]; then
    # Submitter-controlled content AND label: the candidate path derives
    # from changed files, so an instruction-like directory name would
    # otherwise place steering text beside guidance as a plain heading.
    # Keep the label inside the untrusted block with the content.
    block="$(printf '<untrusted_guidance>\n### %s (%s)%s\n\n' \
      "${safe_candidate}" "${source}" "${trunc_note}"
      printf '%s' "${content}" | iconv -c -f UTF-8 -t UTF-8 2>/dev/null \
        | neutralize_tags || true
      printf '\n</untrusted_guidance>')"
  else
    block="$(printf '\n### %s (%s)%s\n\n' "${safe_candidate}" "${source}" "${trunc_note}"
      printf '%s' "${content}" | iconv -c -f UTF-8 -t UTF-8 2>/dev/null || true
      printf '\n')"
  fi
  block_len="$(printf '%s' "${block}" | wc -c)"
  if (( guidance_bytes + block_len > guidance_budget )); then
    guidance_capped=true
    # The candidate label is submitter-controlled: reuse the sanitized,
    # capped display form so the system notice cannot carry steering text.
    printf '\n(Guidance budget exhausted at %s bytes; %s and any further scoped files omitted.)\n' \
      "${guidance_budget}" "${safe_candidate}" >> "${guidance_file}"
    return 0
  fi
  guidance_bytes=$(( guidance_bytes + block_len ))
  printf '%s\n' "${block}" >> "${guidance_file}"
}
seen_reset
for candidate in AGENTS.md CLAUDE.md .agents/AGENTS.md .claude/CLAUDE.md CONTRIBUTING.md .github/copilot-instructions.md; do
  seen_add "${candidate}"
done
# Ancestor walk with zero subprocesses (bash prefix removal, not dirname)
# and a candidate cap: giant PRs could otherwise start tens of thousands of
# processes before the byte budget matters. Root candidates above are always
# included; hitting the cap fails closed (below) instead of trimming
# silently, since later paths' scoped guidance would never be discovered.
candidate_cap=500
guidance_cap_hit=false
while IFS= read -r -d '' changed; do
  if (( ${#MUSE_CANDIDATES[@]} >= candidate_cap )); then
    guidance_cap_hit=true
    echo "::notice::Guidance candidate cap (${candidate_cap}) reached; deeper scoped files omitted."
    break
  fi
  if [[ "${changed}" == */* ]]; then dir="${changed%/*}"; else dir="."; fi
  # Collect the ancestor chain leaf-first, then insert root-to-leaf:
  # scoped-guidance precedence is closest-scope-wins, so parents must
  # precede their children in candidate (and therefore prompt) order —
  # leaf-first insertion would let a later parent read as the override.
  chain=()
  while [[ "${dir}" != "." && "${dir}" != "/" ]]; do
    chain+=("${dir}")
    if [[ "${dir}" == */* ]]; then dir="${dir%/*}"; else dir="."; fi
  done
  # Cap enforced inside the insertion too: a single deeply nested path
  # would otherwise append two candidates per ancestor without rechecking.
  ci=${#chain[@]}
  while (( ci > 0 )) && (( ${#MUSE_CANDIDATES[@]} < candidate_cap )); do
    ci=$(( ci - 1 ))
    seen_add "${chain[${ci}]}/AGENTS.md"
    seen_add "${chain[${ci}]}/CLAUDE.md"
    seen_add "${chain[${ci}]}/.agents/AGENTS.md"
    seen_add "${chain[${ci}]}/.claude/CLAUDE.md"
  done
  if (( ${#MUSE_CANDIDATES[@]} >= candidate_cap )); then
    guidance_cap_hit=true
    echo "::notice::Guidance candidate cap (${candidate_cap}) reached; deeper scoped files omitted."
    break
  fi
done < <(jq -j '[.[] | .filename, (.previous_filename // empty)] | map(select(length > 0))[] + "\u0000"' "${RUNNER_TEMP}/muse-files.json" 2>/dev/null)
if [[ "${guidance_cap_hit}" == "true" ]]; then
  # Fail closed like every other evidence cap (inventory, manifest, diff):
  # later changed paths never contributed scoped candidates, so a
  # governing AGENTS.md/CLAUDE.md may never reach the prompt. Posting a
  # successful marker would claim a complete review over incomplete
  # guidance; exiting nonzero fails the Collect step and Post renders the
  # evidence-collection fallback instead.
  echo "::error::Guidance candidate cap (${candidate_cap}) reached; scoped guidance is incomplete, failing closed to the fallback review."
  exit 1
fi
# Classification in one pass, then ONE emission pass interleaved by
# candidate: for each candidate in scope order, its base copy (trusted,
# or UNTRUSTED custom-base) is immediately followed by its differing
# head copy. Batching every base copy before every head copy would emit
# a modified parent after an unchanged deeper child (parent-base,
# child-base, parent-head), contradicting the prompt's root-first,
# closest-scope-wins precedence and letting the parent read as the
# override. Byte-budget exhaustion still fails closed below, so no
# ordering can publish success over guidance it crowded out.
in_candidate_list() {
  local _needle="$1" _item
  shift
  for _item in "$@"; do
    if [[ "${_item}" == "${_needle}" ]]; then return 0; fi
  done
  return 1
}
# Directory level of a candidate for Muse's first-existing rule: the
# four instruction candidates of one directory share its level; other
# collected files (CONTRIBUTING.md, copilot instructions) are not Muse
# instruction files and keep a level of their own (always applicable).
guidance_level() {
  local _c="$1"
  case "${_c}" in
    AGENTS.md|CLAUDE.md|.agents/AGENTS.md|.claude/CLAUDE.md) printf '.' ;;
    */.agents/AGENTS.md) printf '%s' "${_c%/.agents/AGENTS.md}" ;;
    */.claude/CLAUDE.md) printf '%s' "${_c%/.claude/CLAUDE.md}" ;;
    */AGENTS.md) printf '%s' "${_c%/AGENTS.md}" ;;
    */CLAUDE.md) printf '%s' "${_c%/CLAUDE.md}" ;;
    *) printf 'own:%s' "${_c}" ;;
  esac
}
base_list=()
xbase_list=()
head_list=()
for candidate in "${MUSE_CANDIDATES[@]+"${MUSE_CANDIDATES[@]}"}"; do
  # Explicit base SHA, never bare FETCH_HEAD: later deepens append the head
  # to FETCH_HEAD, so the bare ref could resolve to the wrong commit.
  if [[ "${trust_base_flag}" == "true" ]] \
    && base_probe="$(git show "${MUSE_BASE_SHA_FULL}:${candidate}" 2>/dev/null)"; then
    base_list+=("${candidate}")
    # Head modified this guidance file: emit the differing head copy as
    # UNTRUSTED too, so new or strengthened rules apply to this review.
    # The trusted base copy above still governs, so submitters can add
    # guidance but never silently erase or weaken established rules.
    # Identical content and head deletions stay base-only (the head
    # emission would duplicate, and deleted-file base rules governed
    # the change under review).
    if head_readable "${candidate}" \
      && [[ "$(cat -- "${candidate}")" != "${base_probe}" ]]; then
      head_list+=("${candidate}")
    fi
  else
    # Custom base with available content: emit its version as UNTRUSTED
    # too, so base-side rules that the PR deleted or changed are still
    # visible (emit skips it when head content is identical).
    if [[ "${MUSE_BASE_AVAILABLE:-}" == "true" && -n "${MUSE_BASE_SHA_FULL:-}" ]] \
      && git show "${MUSE_BASE_SHA_FULL}:${candidate}" >/dev/null 2>&1; then
      xbase_list+=("${candidate}")
    fi
    head_list+=("${candidate}")
  fi
done
# First-existing winners per directory level (candidates are already in
# check order within each level): the first base-side candidate whose
# base version exists, and the first candidate readable in the head.
# Lower-priority siblings are not emitted at all; a base winner is still
# emitted when the head winner is a different sibling, because the base
# rules governed the change under review.
base_winners=()
xbase_winners=()
head_winners=()
base_levels=()
xbase_levels=()
head_levels=()
for candidate in "${MUSE_CANDIDATES[@]+"${MUSE_CANDIDATES[@]}"}"; do
  lvl="$(guidance_level "${candidate}")"
  if in_candidate_list "${candidate}" "${base_list[@]+"${base_list[@]}"}" \
    && ! in_candidate_list "${lvl}" "${base_levels[@]+"${base_levels[@]}"}"; then
    base_winners+=("${candidate}")
    base_levels+=("${lvl}")
  fi
  if in_candidate_list "${candidate}" "${xbase_list[@]+"${xbase_list[@]}"}" \
    && ! in_candidate_list "${lvl}" "${xbase_levels[@]+"${xbase_levels[@]}"}"; then
    xbase_winners+=("${candidate}")
    xbase_levels+=("${lvl}")
  fi
  if head_readable "${candidate}" \
    && ! in_candidate_list "${lvl}" "${head_levels[@]+"${head_levels[@]}"}"; then
    head_winners+=("${candidate}")
    head_levels+=("${lvl}")
  fi
done
for candidate in "${MUSE_CANDIDATES[@]+"${MUSE_CANDIDATES[@]}"}"; do
  if in_candidate_list "${candidate}" "${base_winners[@]+"${base_winners[@]}"}"; then
    emit_guidance "${candidate}" base
  fi
  if in_candidate_list "${candidate}" "${xbase_winners[@]+"${xbase_winners[@]}"}"; then
    emit_guidance "${candidate}" xbase
  fi
  if in_candidate_list "${candidate}" "${head_winners[@]+"${head_winners[@]}"}"; then
    # Emit the head winner when it is a differing copy (head_list) or
    # when it differs from the base winner for its level: deleting the
    # base winner (e.g. AGENTS.md) can expose an unchanged lower-priority
    # sibling (e.g. CLAUDE.md) that never entered head_list because its
    # bytes did not change, yet it is the guidance that applies in head.
    if in_candidate_list "${candidate}" "${head_list[@]+"${head_list[@]}"}" \
      || ! in_candidate_list "${candidate}" "${base_winners[@]+"${base_winners[@]}"}"; then
      emit_guidance "${candidate}" head
    fi
  fi
done
if [[ "${guidance_capped}" == "true" || "${guidance_truncated}" == "true" ]]; then
  # Same fail-closed rule as the candidate cap: a budget-dropped or
  # byte-truncated guidance file means rules the reviewer never sees
  # (for base-side files, rules it cannot recover from the head tree).
  # Exiting nonzero fails the Collect step; Post renders the
  # evidence-collection fallback instead of a successful marker.
  echo "::error::Guidance collection incomplete (budget exhausted: ${guidance_capped}, file truncated: ${guidance_truncated}); failing closed to the fallback review."
  exit 1
fi
if [[ ! -s "${guidance_file}" ]]; then
  printf '(No AGENTS.md, CLAUDE.md (including .agents/.claude alternates), CONTRIBUTING.md, or copilot instructions found in this repo.)\n' > "${guidance_file}"
fi
